<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Producción por odontólogo</title><style>@page{size:A4 landscape;margin:12mm}body{font-family:Arial,sans-serif;color:#172b4d;font-size:9px}h1{margin:0 0 4px;font-size:20px}.muted{color:#64748b}.summary{display:flex;gap:20px;flex-wrap:wrap;margin:14px 0;padding:10px;background:#f1f5f9}.summary strong{display:block;font-size:15px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #dbe3ec;padding:6px 4px;text-align:left;vertical-align:top}th{font-size:8px;text-transform:uppercase;color:#64748b}@media print{.no-print{display:none}}</style></head><body><h1>Producción por odontólogo</h1><div class="muted">Generado el {{ now('America/Lima')->format('d/m/Y H:i') }} · Período: {{ $filters['from']->format('d/m/Y') }} al {{ $filters['to']->format('d/m/Y') }} · Procedimiento: {{ $filters['procedure'] ?: 'Todos' }}</div><div class="summary"><div><span>Unidades realizadas</span><strong>{{ $summary['quantity'] }}</strong></div><div><span>Registros</span><strong>{{ $allRows->count() }}</strong></div><div><span>Valor de procedimientos realizados</span><strong>S/ {{ number_format($summary['known_value'],2) }}</strong></div></div><table><thead><tr><th>Fecha</th><th>Paciente / documento</th><th>Plan</th><th>Procedimiento</th><th>Cantidad</th><th>Odontólogo ejecutor</th><th>Valor</th></tr></thead><tbody>@forelse($allRows as $row)@php($patient=$row->session->plan?->paciente)<tr><td>{{ optional($row->session->fecha_sesion)->timezone('America/Lima')->format('d/m/Y H:i') }}</td><td>{{ trim(($patient?->nombres ?? '').' '.($patient?->apellidos ?? '')) }}<br>{{ $patient?->numero_documento }}</td><td>{{ $row->session->plan?->numero ?: '—' }}</td><td>{{ $row->procedure?->codigo_servicio }} · {{ $row->procedure?->nombre_servicio }}</td><td>{{ $row->detail->cantidad_realizada }}</td><td>{{ $row->session->odontologo?->nombre_completo ?: 'Sin ejecutor' }}</td><td>{{ $row->value === null ? 'No disponible' : 'S/ '.number_format($row->value,2) }}</td></tr>@empty<tr><td colspan="7">No hay trabajo realizado para los filtros seleccionados.</td></tr>@endforelse</tbody></table></body></html>
